const JOURNAL_EMPTY_BYTES = new Uint8Array(0);
const JOURNAL_WHITESPACE = /^[\u0009\u000D\u0020]*$/;

function openJournal(chunks) {
  let iterator;
  let acquired = false;
  let sourceDone = false;
  let closed = false;
  let returnHandled = false;
  let closePromise;

  let chunk;
  let offset = 0;
  let parts = [];
  let partsLength = 0;
  let lineNumber = 0;

  const decoder = new TextDecoder("utf-8", {
    fatal: true,
    ignoreBOM: true
  });

  function clearBufferedData() {
    chunk = undefined;
    offset = 0;
    parts = [];
    partsLength = 0;
  }

  function acquireIterator() {
    if (acquired) return;

    try {
      const method = chunks[Symbol.asyncIterator];
      iterator = method.call(chunks);
      acquired = true;
    } catch (error) {
      closed = true;
      clearBufferedData();
      throw error;
    }
  }

  async function callReturn(suppressError) {
    if (!acquired || sourceDone || returnHandled || iterator == null) return;

    returnHandled = true;

    try {
      const method = iterator.return;
      if (typeof method === "function") {
        await method.call(iterator);
      }
    } catch (error) {
      if (!suppressError) throw error;
    }
  }

  async function terminateAfterError() {
    closed = true;
    clearBufferedData();
    await callReturn(true);
  }

  function appendPart(bytes) {
    if (bytes.length === 0) return;
    parts.push(bytes);
    partsLength += bytes.length;
  }

  function consumeLine(hasDelimiter) {
    let bytes;

    if (parts.length === 0) {
      bytes = JOURNAL_EMPTY_BYTES;
    } else if (parts.length === 1) {
      bytes = parts[0];
    } else {
      bytes = new Uint8Array(partsLength);
      let destination = 0;

      for (const part of parts) {
        bytes.set(part, destination);
        destination += part.length;
      }
    }

    parts = [];
    partsLength = 0;
    lineNumber += 1;

    if (
      hasDelimiter &&
      bytes.length !== 0 &&
      bytes[bytes.length - 1] === 0x0d
    ) {
      bytes = bytes.subarray(0, bytes.length - 1);
    }

    const text = decoder.decode(bytes);

    if (JOURNAL_WHITESPACE.test(text)) {
      return undefined;
    }

    try {
      return {
        line: lineNumber,
        ok: true,
        value: JSON.parse(text)
      };
    } catch {
      return {
        line: lineNumber,
        ok: false,
        text
      };
    }
  }

  async function next() {
    if (closed || (sourceDone && partsLength === 0)) {
      return { done: true, value: undefined };
    }

    acquireIterator();

    for (;;) {
      if (closed) {
        return { done: true, value: undefined };
      }

      if (chunk !== undefined) {
        const newline = chunk.indexOf(0x0a, offset);

        if (newline !== -1) {
          appendPart(chunk.subarray(offset, newline));
          offset = newline + 1;

          if (offset === chunk.length) {
            chunk = undefined;
            offset = 0;
          }

          let event;
          try {
            event = consumeLine(true);
          } catch (error) {
            await terminateAfterError();
            throw error;
          }

          if (event !== undefined) {
            return { done: false, value: event };
          }

          continue;
        }

        appendPart(chunk.subarray(offset));
        chunk = undefined;
        offset = 0;
      }

      if (sourceDone) {
        if (partsLength === 0) {
          return { done: true, value: undefined };
        }

        let event;
        try {
          event = consumeLine(false);
        } catch (error) {
          closed = true;
          clearBufferedData();
          throw error;
        }

        if (event !== undefined) {
          return { done: false, value: event };
        }

        return { done: true, value: undefined };
      }

      try {
        const result = await iterator.next();

        if (result.done) {
          sourceDone = true;
          chunk = undefined;
          offset = 0;
        } else {
          const value = result.value;

          if (!(value instanceof Uint8Array)) {
            throw new TypeError("Journal chunks must be Uint8Array values");
          }

          chunk = value;
          offset = 0;
        }
      } catch (error) {
        await terminateAfterError();
        throw error;
      }
    }
  }

  function close() {
    if (closePromise !== undefined) {
      return closePromise;
    }

    if (closed || sourceDone) {
      closed = true;
      clearBufferedData();
      closePromise = Promise.resolve();
      return closePromise;
    }

    closed = true;
    clearBufferedData();

    if (!acquired) {
      closePromise = Promise.resolve();
      return closePromise;
    }

    closePromise = callReturn(false);
    return closePromise;
  }

  return { next, close };
}
